#!/bin/bash
# Check the super orbit in chunks (Orbit/*.lean, generated by orbit_gen.py), in parallel, after check.sh.
#
# usage: check_orbit.sh [kernel|all] [JOBS]      LEAN, LEANLIB as for check.sh
#   kernel   Orbit/K*.lean and OrbitKernel.lean: decide +kernel (about 3 CPU hours)
#   all      also Orbit/N*.lean and OrbitNative.lean: native_decide (about 3 more CPU hours)
#
# native_decide runs the compiled orbit.  Like Lake's `precompileModules`, this script first compiles the modules the
# chunks call (the TM library, Machine, Rules, Macro, Wave, WaveTime) to C with this same lean, links them into a
# shared library with leanc, and loads it with --load-dynlib; without it Lean interprets the same code, ten times
# slower.  Either way native_decide trusts Lean's compiler, not only its kernel.
set -e
cd "$(dirname "$0")"
WHAT=${1:-kernel}
JOBS=${2:-$(nproc)}
LEAN=${LEAN:-lean}
if [ -z "$LEANLIB" ]; then LEANLIB="$(dirname "$(command -v "$LEAN")")/../lib/lean"; fi
TOOLS="$(cd ../../tools/lean && pwd)"
export LEAN LEAN_PATH="$LEANLIB:$TOOLS/out:$(pwd)/out"
[ -f out/WaveTime.olean ] || { echo "run check.sh first"; exit 1; }
mkdir -p out/Orbit

check() {  # check FILE [LEAN OPTIONS]: compile one file to its .olean
  f=$1; shift
  echo "== $f"
  $LEAN "$@" "$f" -o "out/${f%.lean}.olean"
}
export -f check

ls Orbit/K*.lean | xargs -P "$JOBS" -I{} bash -c 'check {}'
check OrbitKernel.lean
[ "$WHAT" = all ] || { echo "ALL CHECKED (kernel)"; exit 0; }

NAT=out/native
mkdir -p $NAT/TM
for f in TM/Basic TM/Fin TM; do (cd "$TOOLS" && $LEAN $f.lean -c "$OLDPWD/$NAT/$f.c" > /dev/null); done
for f in Machine Rules Macro Wave WaveTime; do $LEAN $f.lean -c $NAT/$f.c > /dev/null; done
LEANC=${LEANC:-$(dirname "$(command -v "$LEAN")")/leanc}
$LEANC -shared -fPIC -O3 -DLEAN_EXPORTING -o $NAT/libbb6b.so $NAT/*.c $NAT/TM/*.c
ls Orbit/N*.lean | xargs -P "$JOBS" -I{} bash -c "check {} --load-dynlib=$NAT/libbb6b.so"
check OrbitNative.lean
echo "ALL CHECKED"
